const dTime = t => new Date(t).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
const dSince = ms => { const t0 = Date.now() - ms; let n = 0; for (let i = DHIST.length - 1; i >= 0 && DHIST[i].t >= t0; i--) n++; return n; };
