  const chip = n => `<button class="dk-cchip2${on(n) ? ' on' : ''}" data-act="togcond" data-iid="${x.iid}" data-n="${esc(n)}" aria-pressed="${on(n)}" title="${esc(on(n) ? 'Tap to remove it' : condText(n))}"><span class="ci">${COND_ICON[n] || '•'}</span>${esc(n)}</button>`;
