      <div class="dk-g2"><label><span class="dk-lbl">Rarity</span>${sel('dk-hbR', [['', 'Any']].concat(HB_RAR.map(r => [r, cap(r)])), f.rarity)}</label><label><span class="dk-lbl">Type</span>${sel('dk-hbT', [['', 'Any']].concat(HB_TYPES), f.type)}</label></div>
